insert into tasks (id, guide_id, powertrain_id, title, category, group_name, aliases, live, time_label, difficulty) values
  ('e36-vanos','e36-vanos','s52','VANOS seals & rattle','Engine','timing','{"vanos","vanos seals","vanos rattle","beisan","P1519","bog surge 3000","variable valve timing","11361748819"}',true,'6–8 hr',4);

insert into guides (id, content) values ('e36-vanos', '{"id": "e36-vanos", "title": "VANOS seals & rattle", "fits": "1996–1999 BMW M3 · 3.2 S52 (S52B32US)", "alsoFits": "Same single-VANOS unit on every M50TU / M52 / US S50 six (E36 325i/328i, E34/E39 528i, Z3 2.8 & M) — the S52''s hotter cams make the rattle worse, which is why this guide is here", "category": "Engine", "kind": "repair", "heroId": "e36-vanos-hero", "heroCap": "The VANOS unit bolts to the front of the head on six studs. The solenoid hangs off its left side with the lifting bracket over it; the oil feed hose comes in on a banjo bolt; two big 19 mm plugs give access to the exhaust sprocket bolts behind it.", "glance": {"timeFirst": "6–8 hr", "timeRepeat": "4 hr", "difficulty": 4, "cost": "$45 seals · $100 with rattle kit", "risk": "Engine timing — you lock it, you unlock it, and the order matters · one left-hand-thread bolt inside the piston", "why": "BMW''s single VANOS varies intake cam timing with a hydraulic piston. The piston''s O-ring is nitrile, it hardens in about 20,000 miles, and the Teflon seal on top of it stops sealing. The engine still runs — but with soft low-end torque, a bog-then-surge at 3,000 rpm and a lumpy idle, and most owners have never driven the car without it. Forty-five dollars in seals fixes it. If yours also has the marbles-in-a-can rattle at 1,500–2,500 rpm, a bearing ring fixes most of that in the same session.", "note": "Procedure is Beisan Systems'' published one, which is the procedure — nobody else has written a better one and BMW doesn''t sell the seals. Fastener sizes and torques below are theirs."}, "lifespan": {"title": "When to expect it", "headline": ["Seals: effectively every car — the O-ring is failing by 20,000 miles from new or from the last rebuild", "Rattle: develops as the helical gears wear, typically past 80,000 miles; worse on the M3 than on a 328i"], "earliest": "A ''new'' or ''rebuilt'' BMW unit ships with the same nitrile O-ring, so a recent replacement doesn''t exempt you", "detail": "Beisan''s diagnosis is blunt: unless the seals have already been done with a Viton O-ring, they''re gone. The Teflon seal rides on the O-ring; when the O-ring shrinks and flattens the Teflon stops pressing on the cylinder wall and oil bypasses the piston, so the cam can''t hold its commanded position. The rattle is a separate problem — lash in the helical gears on the cam, sprocket and splined shaft lets the shaft knock axially in the piston bearing.", "factors": ["Never had a Viton O-ring fitted", "M3 cams (higher spring load = harder lash = louder rattle)", "Aftermarket cams (Schrick, Sunbelt) — same reason"], "inspect": ["Warm idle in a quiet garage: a rattle that comes and goes between 1,500 and 2,500 rpm, from the front of the head", "Roll-on from 2,000 rpm in third: a soft spot then a surge near 3,000"], "confidence": {"level": "high", "n": 4, "note": "Beisan''s failure analysis is the reference; three owner threads and a Bimmerforums FAQ agree with it and with each other."}}, "should": {"yesIf": ["Soft below 3,000 rpm, then a surge — the classic sign", "Idle louder and less steady than it should be; occasional idle hiccup", "Rattle from the top-front of the engine at light throttle, 1,500–2,500 rpm", "Fault code P1519 (BMW 212): VANOS mechanically stuck", "You don''t know when — or whether — the seals were done"], "codes": ["P1519"], "notes": ["This is not a dealer job any more; BMW quotes a complete unit (~$1,000+) with the same O-ring inside. The $30 seal kit is the repair.", "You''ll need the timing tools: cam lock blocks, a crank lock pin, and a sprocket turner. Aftermarket sets are $50–90 and this is one of four or five jobs on the engine that use them.", "Valve cover gasket: it''s off anyway. If it''s past 40k or you don''t know, replace it — Beisan calls it required past 80k because a reused old gasket leaks once disturbed.", {"text": "Rattle fix adds the bearing ring, Beisan''s chamfer-less 18 mm socket and nylon vise jaws, and a mounted bench vise. About an extra hour, done with the unit on the bench.", "only": ["rattle"]}], "confidence": {"level": "high", "n": 4, "note": "Symptom list is Beisan''s and matches owner reports word for word."}}, "variants": {"question": "Seals only, or seals and the rattle?", "hint": "Everyone needs the seals. The rattle fix is a tighter-tolerance bearing ring inside the piston that takes out the axial play the worn helical gears exploit — it needs a bench vise and two small Beisan tools.", "options": [{"id": "seals", "label": "Seals only", "when": "No rattle, or you''re not chasing it yet. Kit + gasket + two washers.", "oeOnly": true}, {"id": "rattle", "label": "Seals + rattle fix", "when": "Rattle at 1,500–2,500 rpm. Adds the bearing ring, modified socket, jaw liners and a vise."}]}, "parts": [{"tier": "oem", "name": "Single VANOS seals kit — Beisan BS011", "pn": "BS011", "note": "OEM-spec Teflon seal + Viton O-ring. The only source", "price": "$30", "links": [{"store": "Beisan Systems", "url": "https://beisansystems.com/product/single-vanos-seals-repair-kit/"}, {"store": "BimmerWorld", "url": "https://www.bimmerworld.com/Engine/Camshafts/VANOS-Rattle-Repair-Kit-Beisan-E36-E34-E39-Z3.html"}]}, {"tier": "oe", "name": "VANOS-to-head gasket", "pn": "11361740840", "note": "Asymmetric; mounts on the two dowels", "price": "$8", "links": []}, {"tier": "oe", "name": "Oil hose banjo washers ×2", "pn": "32411093596", "note": "One each side of the hose end. Never reuse", "price": "$1", "links": []}, {"tier": "oem", "name": "Rattle repair kit — Beisan BS012", "pn": "BS012", "note": "Ground bearing ring with tight height tolerance", "price": "$30", "links": [{"store": "Beisan Systems", "url": "https://beisansystems.com/product/single-vanos-rattle-repair-kit-6-cyl/"}], "only": ["rattle"]}, {"tier": "oem", "name": "18 mm modified socket (BS093) + nylon vise jaw liners (BS0091)", "pn": "BS093 · BS0091", "note": "Chamfers removed so it grips a 3 mm-tall cap. Beisan says the liners are non-negotiable", "price": "$7 · $15", "links": [], "only": ["rattle"]}, {"tier": "oem", "name": "New thrust bearing set — Beisan BS013", "pn": "BS013", "note": "Optional: two new roller bearings for the piston. Worth it on a high-mile unit", "price": "$20", "links": [], "only": ["rattle"]}, {"tier": "oe", "name": "Valve cover gasket set (black plastic cover)", "pn": "11120034108", "note": "Perimeter + 6 plug-well gaskets. Recommended, see notes", "price": "$35–45", "links": []}, {"tier": "oe", "name": "Valve cover bolt grommets ×15 · oil fill neck gasket", "pn": "11121437395 · 11127526447", "note": "Grommets go hard and let the cover weep", "price": "$20 · $3", "links": []}, {"tier": "oem", "name": "Three Bond 1209 sealant (Beisan BS0SS) or Reinzosil", "pn": "BS0SS", "note": "Thin coat at the two VANOS/head corners and the rear half-moons only", "price": "$12–18", "links": []}, {"tier": "oe", "name": "Fragile bits: engine-cover caps ×4, shroud rivets ×2, duct rivets ×2", "pn": "11121726089 · 17111712963 · 51481915964", "note": "You''ll break at least one", "price": "$15", "links": []}], "aftermarket": [{"name": "Timing tool kit (cam blocks, crank pin, sprocket turner, tensioner pin)", "note": "The four BMW special tools (11 3 240, 11 2 300, 11 5 490, 11 3 292) in one aftermarket case. Buy once — same kit does cams, timing chain and head work.", "price": "$50–90", "signal": "Required", "links": []}, {"name": "Rebuilt VANOS unit with Beisan seals (Dr. VANOS, shops)", "note": "Exchange units come pre-sealed and often with the rattle fix done. Saves the bench work; you still do everything else in this guide.", "price": "$300–450 + core", "signal": "Shortcut", "links": []}, {"name": "Turner / VAC VANOS oil line upgrade", "note": "Braided replacement for the factory oil feed hose. Only if yours is weeping at the crimp; not a performance part.", "price": "$60–90", "signal": "If leaking", "links": []}], "tools": [{"name": "Timing tools: camshaft lock blocks, crankshaft lock pin, sprocket turner, tensioner lock pin (a 3d finishing nail works for the last one)"}, {"name": "32 mm thin fan wrench + pulley holder (or long screwdriver), for the fan"}, {"name": "1/2\": 22 mm and 19 mm sockets, long-arm ratchet. 3/8\": 13, 10 deep, 10, E10 Torx, 8 mm, extensions. 24 mm combination wrench for the cam hexes. 19 mm combination for the banjo"}, {"name": "Torque wrench(es) covering 8 Nm to 50 Nm"}, {"name": "Razor knife, straight pick, gasket scraper / plastic putty knife, needle file, small mirror, magnet pickup, medium-nose pliers"}, {"name": "Brake cleaner, water-based cleaner, fresh 5W-30 for assembly, oil pan, a quilt or pad to kneel on, three small towels, a sandwich bag"}, {"name": "Bench vise, 4\" or larger, bolted down. T30 Torx bit. 400-grit sandpaper. Heat gun", "only": ["rattle"]}], "before": ["Engine stone cold. Right and left in this guide mean standing at the front of the car looking at the engine.", "Manual: gearbox in neutral so you can turn the crank. Chock the rear wheels — you''ll be under the front.", "Read the timing chapter twice before you touch a bolt. The whole job is: lock the cams, lock the crank, pull the unit, put it back on the first spline that engages, unlock. Nothing here is hard; getting it out of order is.", "Lay parts out on a tray in the order they come off. There are a lot of 10 mm fasteners that look alike and aren''t."], "chapters": [{"id": "access", "title": "Access", "blurb": "Fan, engine covers, coils, valve cover — the front of the head laid bare."}, {"id": "lock", "title": "Lock the timing", "blurb": "Crank at TDC on the pin, both cams on their blocks. Do this before anything comes off the VANOS."}, {"id": "out", "title": "VANOS off", "blurb": "Hose, bracket, solenoid plug, six nuts, exhaust sprocket bolts — and the trick to wiggling it off."}, {"id": "bench", "title": "On the bench", "blurb": "New seals; and, if you chose it, the bearing ring."}, {"id": "back", "title": "Back on & unlock", "blurb": "The install is the critical step. Then the sprocket bolts, then unlock in reverse."}, {"id": "close", "title": "Close up", "blurb": "Sealant in two places only, valve cover, coils, fan. First start and break-in."}], "steps": [{"n": 1, "chapter": "access", "title": "Fan and shroud out", "blocks": [{"t": "text", "b": "Radiator cover off, the two expanding rivets at the top of the fan shroud, then the fan: 32 mm thin wrench on the clutch nut, pulley holder on the pump. Left-hand thread — loosen clockwise as you look at it. Lift fan and shroud out together. (Same moves as the cooling guide, step 3 and 4.)"}]}, {"n": 2, "chapter": "access", "title": "Engine covers, vent hose, coil harness", "blocks": [{"t": "text", "b": "Pry the centre caps off both plastic engine covers; two 10 mm nuts on the left cover (unscrew the oil cap first, put it back after), two 10 mm bolts on the right. Valve-cover vent hose at the right-front corner: squeeze the connector''s ring clip on both sides and wiggle it off — don''t yank, the hose is brittle."}, {"t": "text", "b": "Coils: lift the metal lock on each connector and pull the plug. Unscrew the harness ground wire from the valve-cover stud between coils 2 and 3 (8 mm). Pry the harness rail''s clips, lift the whole rail and lay it over the left side of the bay. Two 10 mm bolts per coil; pull all six and keep them in order. Ground straps at cylinders 1 and 6, 8 mm."}]}, {"n": 3, "chapter": "access", "title": "Valve cover off", "blocks": [{"t": "text", "b": "Eleven 10 mm perimeter bolts, each with a washer and rubber grommet — the one in the left-rear corner is the one everyone misses. Then the four centre bolts/studs. Slide a plastic putty knife between gasket and head along the front to break the bond, and lift. It''ll stick at the two rear half-moons where the factory RTV is; pull the gasket up gently there. Keep the gasket with the cover; lift out the six plug-well gaskets."}, {"t": "text", "b": "Pull up the intake cam cover (the long plastic strip clipped over the intake cam) and set it aside."}, {"t": "note", "b": "If the gasket is stuck to the head, work the blade in from an edge rather than pulling — an old gasket shatters into pieces that end up in the head."}]}, {"n": 4, "chapter": "lock", "title": "Crank to TDC, pin it", "blocks": [{"t": "text", "b": "22 mm on the crank pulley bolt, long ratchet. Turn clockwise until the cylinder-1 intake and exhaust lobes point at each other at about 45°, and the square on the rear of each cam sits flush with the head surface. Then fine-tune to the TDC marks on the timing cover and balancer (about 11 o''clock, use the mirror). Front up on stands."}, {"t": "text", "b": "The crank lock hole is at the right-rear of the block behind a rubber plug — pry it out with a Torx bit through its eyelet. Poke a narrow driver in to feel the depth, then push the lock pin in to the same depth. Try the crank with the 22 mm: it should be locked with only a hair of play. If the pin won''t go home, nudge the crank a degree at a time. Lower the car."}, {"t": "ill", "id": "e36-vanos-timing", "cap": "Locked: crank pin in the block behind the plug, both rear cam squares flush and captured by the lock blocks, bracket bolted over the blocks."}]}, {"n": 5, "chapter": "lock", "title": "Cam lock blocks on", "blocks": [{"t": "text", "b": "Remove the three valve-cover studs at the rear of the head (10 mm, no room for an extension on the E36) and scrape the old sealant off the half-moon corners. Exhaust block first (its bolt hole to the right): sit it on the exhaust cam''s rear square, put the 24 mm on the cam''s hex and rock the cam until the block sits flush on the head. Intake block the same way (bolt hole to the left). Bolt the bracket across both blocks, 13 mm."}, {"t": "warn", "b": "From here until the blocks come off again, nothing turns. If a wrench slips and a cam moves, stop and re-seat the blocks before continuing."}]}, {"n": 6, "chapter": "out", "title": "Hose, bracket, plug, vacuum pipe", "blocks": [{"t": "text", "b": "VANOS oil hose: 19 mm banjo bolt, two washers (one each side of the hose eye) — bin them. Engine lift bracket over the solenoid: two 13 mm bolts. Solenoid connector: follow the wire up to the plug, press the spring clip, pull. Move the vent hose and oil hose out to the right of the filter canister for room."}, {"t": "text", "b": "The vacuum pipe bracket sits on two of the VANOS studs: two 10 mm nuts (one standard, one deep), pull the pipe off the studs and lay it down on the thermostat and lower hose — the side hoses give you enough slack."}]}, {"n": 7, "chapter": "out", "title": "Exhaust sprocket bolts, tensioner pin, six nuts", "blocks": [{"t": "text", "b": "The two large plugs on the face of the VANOS are access bolts: 19 mm, 1/2-inch drive. Behind them are the four E10 Torx bolts holding the exhaust sprocket. Stuff a towel under the sprocket first so a dropped bolt can''t reach the sump; take out all four; retrieve anything dropped with the magnet, not fingers."}, {"t": "text", "b": "Press the chain tensioner down and slide the lock pin (or nail) in on top of the chain — not under it, or you''ll tension the chain by accident. Then the remaining four 10 mm nuts on the lower half of the VANOS face (you already have two off with the vacuum pipe)."}, {"t": "ill", "id": "e36-vanos-hero", "cap": "Fastener map on the face of the unit: two 19 mm access plugs over the exhaust sprocket, six 10 mm nuts along the bottom, banjo bolt top-right, solenoid and lift bracket on the left."}]}, {"n": 8, "chapter": "out", "title": "Wiggle it off", "blocks": [{"t": "text", "b": "Towels over the A/C belt and lower hose; a sandwich bag over the oil feed hole — a lot of oil comes out of the unit. Mount the sprocket turner on the exhaust sprocket. Pull the VANOS forward while turning the exhaust sprocket clockwise: that slackens the chain, lets the intake sprocket turn clockwise, and lets the splined shaft back out of it. Take it to a pan, tilt to drain both the relief spout and the feed hole, and peel the old gasket off the head."}]}, {"n": 9, "chapter": "bench", "title": "Open the cylinder, check the piston", "blocks": [{"t": "text", "b": "Work over a table so nothing can fall far. Five 10 mm bolts hold the cylinder cover; lift cover, splined shaft and piston out together and drain. Run a finger round the cylinder wall — glass smooth, wear tracks are fine. Now slide the piston in and out: it''s loose. That looseness is the whole problem."}]}, {"n": 10, "chapter": "bench", "title": "Rattle fix: new bearing ring", "only": ["rattle"], "blocks": [{"t": "text", "b": "Rock the splined shaft in the piston before you start: in-and-out (axial) play is the rattle; side-to-side is normal. Nylon liners on the vise. Press piston and cover together, stand them vertically in the vise with the piston at the outer jaw, and turn the cover so the raised bolt-hole bosses are caught by the liner notches — that''s what stops it spinning. Clamp hard."}, {"t": "text", "b": "Break the piston cap loose with the 18 mm chamfer-less socket and a long 1/2-inch bar, holding the socket onto the 3 mm-tall head with your other hand. Heat gun on the threads if it fights. Loosen, don''t remove. Re-clamp on the splined shaft alone, spin the cap off by hand, and lift out: top washer, top thrust bearing, then the T30 bolt in the middle."}, {"t": "warn", "b": "That T30 bolt is a LEFT-hand thread. Clockwise to remove. It''s 8 Nm — if it feels like more, you''re tightening it."}, {"t": "text", "b": "Centre washer, bottom thrust bearing, then pull the piston off the shaft and the cover. Fingers inside the old ring, wiggle it out; the bottom washer under it comes out with a 90° pick. Clean everything in brake cleaner — the fit check only works on clean parts."}, {"t": "ill", "id": "e36-vanos-bearing", "cap": "Stack order, bottom to top: washer, ring (new one marked BS), bottom thrust bearing, centre washer on the shaft, T30 left-hand bolt, top thrust bearing, washer, cap."}, {"t": "text", "b": "Rebuild in that order with the BS ring (and new thrust bearings if you bought them). T30 to 8 Nm, left-hand. Hand-tighten the cap, re-clamp with the bosses in the notches, cap to 40 Nm. Now the test: hold the piston and turn the shaft — slight resistance and no rocking is perfect. Rocking = still loose: sand the ring 10 s a side on 400 grit and re-test. Binds = too tight: sand the centre washer instead. Beisan says an M3 needs zero play and a little pre-load. Oil through the hole in the cap."}, {"t": "torque", "label": "Piston bolt/cap (18 mm modified socket)", "nm": 40, "c": {"level": "high", "n": 1, "note": "Beisan rattle procedure. Only source, but it''s the source."}}, {"t": "torque", "label": "Bearing / splined-shaft bolt (T30, LEFT-hand)", "nm": 8, "c": {"level": "high", "n": 1, "note": "Beisan rattle procedure."}}]}, {"n": 11, "chapter": "bench", "title": "New seals on the piston", "blocks": [{"t": "text", "b": "Razor across the old Teflon ring in its groove, rocking the blade — it comes out in one piece. Same for the O-ring under it; look at it: flat top and bottom, shrunk, hard. Wipe the groove to bare metal. New O-ring (brown) in first: hook one side into the groove, stretch the rest over, then run a pick round to make sure it isn''t twisted."}, {"t": "text", "b": "Teflon seal: if the room is under 18 °C soak it in warm water two minutes first. Kneel on the pad, hook one side in, stretch it evenly over — it takes real force and slides on the rim as it goes, that''s normal. It''ll sit loose in the groove; that''s expected."}, {"t": "ill", "id": "e36-vanos-piston", "cap": "Cross-section of the piston groove: Viton O-ring at the bottom pushing the rectangular Teflon seal out against the cylinder wall. When the O-ring shrinks, the Teflon stops touching and oil bypasses."}, {"t": "text", "b": "Resize the Teflon: oil the seal, the piston shoulder and the whole cylinder wall including the chamfer. Push the shaft in to separate piston from cover, tip the piston into the cylinder at about 30° and roll it flat — the chamfer gathers the excess seal into the groove. If it binds, back out and try again; each attempt shrinks it a bit. Push fully home, leave it two minutes, pull it out: the seal is now sized. Reinstall, seat the cover, five bolts criss-cross."}, {"t": "torque", "label": "Cylinder cover bolts (M6 ×5)", "nm": 10, "c": {"level": "high", "n": 2, "note": "Beisan; matches the Bentley M6 figure."}}, {"t": "note", "b": "Push the shaft in and out now. It''s stiff. Compare that with how it slid before and you''ve just confirmed the diagnosis."}]}, {"n": 12, "chapter": "bench", "title": "Clean everything", "blocks": [{"t": "text", "b": "Head face where the VANOS sits, the studs, the valve-cover rail — brake cleaner and towels, scraper for the sealant at the half-moons. Every nut, bolt, washer and grommet; the coil feet; the ground-strap ends. Old sealant off the valve-cover gasket if you''re keeping it (pick, fingernail), then water-based cleaner on the gasket and cover — brake cleaner swells rubber."}, {"t": "text", "b": "New valve-cover gasket now if you''re doing it: fifteen new grommets onto the bolts, cut the old fill-neck gasket off the cap and fit the new one."}]}, {"n": 13, "chapter": "back", "title": "Gasket, then the install", "blocks": [{"t": "text", "b": "New VANOS gasket onto the head — asymmetric, top corners over the two dowels, flat to the face. Splined shaft pushed all the way INTO the unit. Sprocket turner on the exhaust sprocket: turn it clockwise as far as it goes, which turns the intake sprocket clockwise as far as it goes."}, {"t": "warn", "b": "The next paragraph is the step that decides the job. Shaft fully in, sprockets fully clockwise, and the unit goes on at the first spline that will take it. Skip any of those and the cam timing is off by a tooth."}, {"t": "text", "b": "Offer the unit up onto the studs and feed the splined shaft toward the intake sprocket. Rotate the unit slightly by hand until you feel the shaft find teeth and start in — Beisan''s newer note is to find the pair of teeth where it slides in on its own without turning the exhaust sprocket, then press it home with the heel of your hand and nut it. If it won''t slide, the older method: sprocket turner on the exhaust sprocket, turn it ANTICLOCKWISE while pushing the unit in, and take the first engagement. Seat the top corners on the dowels."}, {"t": "ill", "id": "e36-vanos-install", "cap": "Splined shaft: helical teeth outside for the sprocket, inside for the cam. Pushing it in advances the cam; that''s why it must go on fully retracted, on the first tooth."}, {"t": "text", "b": "Four of the six 10 mm nuts (leave the two the vacuum-pipe bracket uses), tightened evenly back and forth."}, {"t": "torque", "label": "VANOS mounting nuts (M6 ×6)", "nm": 8, "c": {"level": "high", "n": 2, "note": "Beisan 8 Nm; Bentley gives 10 for M6 generally. Go with 8 — the studs are in aluminium."}}]}, {"n": 14, "chapter": "back", "title": "Sprocket bolts, plugs, pipe, hose", "blocks": [{"t": "text", "b": "Pull the tensioner pin. Towel under the sprocket again, four E10 bolts in criss-cross, then the two 19 mm access plugs. Vacuum pipe back onto its two studs, its two nuts, then check all six VANOS nuts at 8 Nm. Solenoid plug in until it clicks. Lift bracket: long bolt top, short bolt bottom. Oil hose with two NEW washers — washer, hose, washer, bolt — a screwdriver between hose and solenoid stops it turning."}, {"t": "torque", "label": "Exhaust sprocket bolts (E10 ×4)", "nm": 20, "c": {"level": "high", "n": 2, "note": "Beisan; Bentley agrees."}}, {"t": "torque", "label": "Sprocket access plugs (19 mm ×2)", "nm": 50, "c": {"level": "high", "n": 1, "note": "Beisan."}}, {"t": "torque", "label": "Lift bracket bolts (13 mm ×2)", "nm": 8, "c": {"level": "community", "n": 1, "note": "Beisan gives 8 Nm here; the same bracket at the thermostat housing is 22. Follow Beisan for this location — the lower bolt goes into the VANOS casting."}}, {"t": "torque", "label": "Oil hose banjo bolt (19 mm)", "nm": 32, "c": {"level": "high", "n": 1, "note": "Beisan. Hard to get a torque wrench on; ''firm with a combination wrench'' is what most people do."}}]}, {"n": 15, "chapter": "back", "title": "Unlock", "blocks": [{"t": "text", "b": "Bracket off, both cam blocks off. Three rear valve-cover studs back in, 8 Nm. Front up on stands, pull the crank pin (wiggle it), press the rubber plug back into the hole. Down off the stands."}, {"t": "note", "b": "Want to be sure? Before the valve cover goes on, turn the crank two full turns clockwise by hand with the 22 mm and check that the cams come back to their 45°-pointing-at-each-other position at TDC. If they do, you took the first tooth."}]}, {"n": 16, "chapter": "close", "title": "Sealant in two places, valve cover on", "blocks": [{"t": "text", "b": "Intake cam cover back on (arched end to the rear), pressed down until it clips. Gaskets into the valve cover. A THIN smear of 3Bond at the two spots where the VANOS meets the head under the gasket, and at the two rear half-moon corners — nowhere else. Two minutes to skin, then cover on, rear cables into their slot."}, {"t": "text", "b": "Eleven perimeter bolts plus the four centre bolts/studs, working back and forth so the cover pulls down evenly, until they bottom on the head. Then torque."}, {"t": "torque", "label": "Valve cover bolts (M6 ×15)", "nm": 10, "c": {"level": "high", "n": 3, "note": "Beisan and Bentley agree. Bolts bottom out on the head — the grommets set the clamp, not the torque."}}]}, {"n": 17, "chapter": "close", "title": "Coils, hoses, covers, fan", "blocks": [{"t": "text", "b": "Ground straps at 1 and 6 (bent end on the stud: cylinder 1 towards the top corner, cylinder 6 towards the bottom). Coils back in their own wells, two bolts each, alternating so they pull down square — the boot won''t fully seat on the plug until the bolts are snug, that''s normal. Harness rail clipped to the cover, six connectors locked, ground wire to the stud between 2 and 3. Vent hose snapped onto its neck. Engine covers. Fan (anticlockwise onto the pump, tap the wrench to seat), shroud rivets, radiator cover."}, {"t": "torque", "label": "Coil bolts (M6 ×12)", "nm": 10, "c": {"level": "high", "n": 2, "note": "Beisan; matches the plugs & coils guide."}}]}, {"n": 18, "chapter": "close", "title": "First start", "blocks": [{"t": "text", "b": "Wait an hour for the sealant. First start it may hiccup at idle once or twice — air in the VANOS. Check oil (you lost some), and top the coolant and bleed if you had the tank off. Then drive it: Beisan says about 100 miles of town driving to bed the new seals before the 3,000-rpm transition is fully smooth."}, {"t": "warn", "b": "A rough idle that doesn''t settle, a check-engine light, or a cam-position code means the timing is off a tooth. Don''t drive it; go back to step 13."}]}], "alsoReplace": [{"name": "Valve cover gasket + 15 grommets", "why": "Cover is off. Past 40k it''s prudent, past 80k it''s required — an old gasket that''s been disturbed leaks."}, {"name": "VANOS oil feed hose", "why": "If the crimp is weeping now, it''s the same 19 mm bolt you have out. Genuine 11361703697 or a braided replacement."}, {"name": "Cam position / crank sensors", "why": "Cam sensor lives on the front of the head right here; a $40 part that causes the same P-codes people blame on the VANOS."}, {"name": "Fan clutch", "why": "It''s off. Rocks on its hub or freewheels hot: replace."}], "check": {"tab": "VANOS or not?", "title": "Is it the VANOS?", "illId": "e36-vanos-hero", "illCap": "What else lives on the front of the head.", "rows": [{"see": "Soft below 3k, surge at 3k, lumpy idle", "means": "Seals. Assume it unless done with Viton.", "do": "This guide."}, {"see": "Rattle 1,500–2,500 rpm, top front, warm", "means": "Helical gear lash knocking the piston bearing.", "do": "Seals + rattle route."}, {"see": "P1519 / BMW 212", "means": "VANOS stuck — seals, or a bad solenoid.", "do": "Seals first; solenoid if it persists."}, {"see": "Rough idle right after the job, cam codes", "means": "Timing off a tooth.", "do": "Re-lock, pull, reinstall on the first spline."}, {"see": "Ticking that follows revs, top of the engine, any rpm", "means": "Lifters / low oil, not VANOS.", "do": "Oil level and condition first."}, {"see": "Oil on the front of the head below the unit", "means": "Banjo washers or the VANOS gasket.", "do": "Two washers, one gasket."}], "c": {"level": "high", "n": 3, "note": "Beisan diagnostics plus owner threads."}}, "aftercare": ["Oil level after the first drive; expect to add a little.", "Look at the banjo bolt and the head/VANOS joint at 200 miles for weeps.", "Judge the result after 100 miles, not 10 — the Teflon needs to bed."], "disagreements": [{"topic": "New BMW unit vs seals", "pos": "Dealers and some shops still sell a complete unit.", "call": "Same nitrile O-ring inside. Do the seals — or buy a rebuilt unit that already has Beisan seals in it."}, {"topic": "Rattle: replace the helical gears?", "pos": "Some owners had dealers replace cam, sprocket and splined shaft.", "call": "Beisan''s data: it comes back as the new gears wear. The bearing ring is the practical fix."}, {"topic": "Torque on the lift bracket", "pos": "8 Nm (Beisan, at the VANOS) vs 22 Nm (Bentley, at the thermostat housing).", "call": "Different location, different casting. 8 here."}, {"topic": "Timing tools", "pos": "Some do it without lock blocks, marking the sprockets.", "call": "Don''t. Tools are $60 and the alternative is a tooth off."}], "sources": ["Beisan Systems — Single Vanos 6-cyl (E36, E34, E39) seals procedure: the full R&R with fastener sizes and torques", "Beisan Systems — Single Vanos Rattle 6-cyl procedure: bearing ring replacement, vise technique, fit adjustment", "Beisan Systems — ''Finding the smart teeth'' install video (the no-turn method)", "Bentley E36 service manual torque values via owner transcriptions (sprocket bolts, valve cover)", "Bimmerforums E36 M3 VANOS FAQ and owner write-ups (symptoms, break-in, tool kits)"], "embeds": [{"id": "8HKRaEZOhPc", "note": "Beisan''s short clip on finding the spline pair that lets the unit slide on without turning the exhaust sprocket — watch before step 13."}]}'::jsonb);

commit;
